local StuccoReliefMaker = {}
local PRODUCTS = {
    simple_lime_stucco = { name = "Preprost apneno omet", clayCost = 2, stoneCost = 1, time = 4, cost = 50, beauty = 22, happiness = 1, description = "Preprost apneno omet za stene." },
    painted_stucco_relief = { name = "Poslikana ometna reliefa", clayCost = 2, stoneCost = 1, paintCost = 1, time = 7, cost = 140, beauty = 38, happiness = 2, prestige = 2, description = "Poslikana ometna reliefa za trgovce." },
    marble_dust_stucco = { name = "Marmornatiprahni omet", marbleCost = 2, clayCost = 2, stoneCost = 1, paintCost = 1, time = 10, cost = 360, beauty = 52, happiness = 2, prestige = 6, description = "Marmornatiprahni omet za plemiče." },
    silver_gilt_stucco = { name = "Srebrnoslikani omet", marbleCost = 2, silverCost = 1, clayCost = 2, stoneCost = 1, paintCost = 1, time = 14, cost = 880, beauty = 65, happiness = 3, prestige = 14, description = "Srebrnoslikani omet za visoke plemiče." },
    gold_leaf_stucco = { name = "Zlatolistni omet", marbleCost = 2, goldCost = 1, silverCost = 1, clayCost = 2, stoneCost = 1, paintCost = 1, jewelCost = 1, time = 18, cost = 1900, beauty = 78, happiness = 5, prestige = 27, description = "Zlatolistni omet z draguljem za visoko plemstvo." },
    royal_grand_stucco = { name = "Kraljevski veliki omet", marbleCost = 3, goldCost = 2, silverCost = 2, clayCost = 3, stoneCost = 2, paintCost = 2, jewelCost = 2, pearlCost = 2, time = 25, cost = 4200, beauty = 92, happiness = 12, prestige = 58, description = "Veliki kraljevski omet z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    stucco_workshop = { name = "Ometna delavnica", cost = { gold = 240, wood = 100, stone = 140, clay = 6 }, upkeep = 5, qualityBonus = 5 },
    plaster_loft = { name = "Ometna podstrešje", cost = { gold = 880, wood = 240, stone = 280, marble = 4, paint = 6 }, upkeep = 20, qualityBonus = 18 },
    master_plasterer_atelier = { name = "Mojstrski ometarski atelje", cost = { gold = 2500, wood = 360, stone = 520, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_stucco_palace = { name = "Kraljevska ometna palača", cost = { gold = 10500, wood = 580, stone = 800, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
StuccoReliefMaker.clayStock = 14; StuccoReliefMaker.stoneStock = 14; StuccoReliefMaker.marbleStock = 10; StuccoReliefMaker.paintStock = 10; StuccoReliefMaker.silverStock = 6; StuccoReliefMaker.goldStock = 6; StuccoReliefMaker.jewelStock = 4; StuccoReliefMaker.pearlStock = 4
StuccoReliefMaker.productStock = {}; StuccoReliefMaker.buildings = {}; StuccoReliefMaker.maker = nil; StuccoReliefMaker.activeMaking = {}; StuccoReliefMaker.totalProducts = 0; StuccoReliefMaker.dayTimer = 0
function StuccoReliefMaker.init() StuccoReliefMaker.clayStock=14; StuccoReliefMaker.stoneStock=14; StuccoReliefMaker.marbleStock=10; StuccoReliefMaker.paintStock=10; StuccoReliefMaker.silverStock=6; StuccoReliefMaker.goldStock=6; StuccoReliefMaker.jewelStock=4; StuccoReliefMaker.pearlStock=4; StuccoReliefMaker.productStock={}; StuccoReliefMaker.buildings={}; StuccoReliefMaker.maker=nil; StuccoReliefMaker.activeMaking={}; StuccoReliefMaker.totalProducts=0; StuccoReliefMaker.dayTimer=0; print("[StuccoReliefMaker] Royal Stucco Relief Maker System initialized (6 products, 4 buildings)") end
function StuccoReliefMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; StuccoReliefMaker.maker={name=n or ("Ometar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ometar najet: %s (spretnost: %d)",StuccoReliefMaker.maker.name,s),"success") end; return true end
function StuccoReliefMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function StuccoReliefMaker.build(id) local ok,e=StuccoReliefMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(StuccoReliefMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function StuccoReliefMaker.getQualityBonus() local b=0; for _,bd in ipairs(StuccoReliefMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function StuccoReliefMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayCost and StuccoReliefMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.stoneCost and StuccoReliefMaker.stoneStock<(d.stoneCost or 0) then return false,"Premalo kamna" end; if d.marbleCost and StuccoReliefMaker.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.paintCost and StuccoReliefMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and StuccoReliefMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and StuccoReliefMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and StuccoReliefMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and StuccoReliefMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #StuccoReliefMaker.buildings==0 then return false,"Potrebna ometna delavnica" end; if not StuccoReliefMaker.maker then return false,"Potreben ometar" end; return true end
function StuccoReliefMaker.make(pt,qty) qty=qty or 1; local ok,e=StuccoReliefMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayCost then StuccoReliefMaker.clayStock=StuccoReliefMaker.clayStock-d.clayCost*qty end; if d.stoneCost then StuccoReliefMaker.stoneStock=StuccoReliefMaker.stoneStock-d.stoneCost*qty end; if d.marbleCost then StuccoReliefMaker.marbleStock=StuccoReliefMaker.marbleStock-d.marbleCost*qty end; if d.paintCost then StuccoReliefMaker.paintStock=StuccoReliefMaker.paintStock-d.paintCost*qty end; if d.silverCost then StuccoReliefMaker.silverStock=StuccoReliefMaker.silverStock-d.silverCost*qty end; if d.goldCost then StuccoReliefMaker.goldStock=StuccoReliefMaker.goldStock-d.goldCost*qty end; if d.jewelCost then StuccoReliefMaker.jewelStock=StuccoReliefMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then StuccoReliefMaker.pearlStock=StuccoReliefMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if StuccoReliefMaker.maker then t=math.max(1,t-math.floor(StuccoReliefMaker.maker.skill/13)) end; table.insert(StuccoReliefMaker.activeMaking,{id="stucco_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ometanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function StuccoReliefMaker.completeMaking(m) local q=1.0+(StuccoReliefMaker.getQualityBonus()/100); if StuccoReliefMaker.maker then q=q+(StuccoReliefMaker.maker.skill/140) end; q=math.min(2.5,q); StuccoReliefMaker.productStock[m.productType]=(StuccoReliefMaker.productStock[m.productType] or 0)+m.quantity; StuccoReliefMaker.totalProducts=StuccoReliefMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if StuccoReliefMaker.maker then StuccoReliefMaker.maker.itemsMade=StuccoReliefMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then StuccoReliefMaker.maker.skill=math.min(100,StuccoReliefMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Omet izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"stucco.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function StuccoReliefMaker.update(dt) if not _G.state then return end; StuccoReliefMaker.dayTimer=StuccoReliefMaker.dayTimer+dt; if StuccoReliefMaker.dayTimer>=30 then StuccoReliefMaker.dayTimer=0; for i=#StuccoReliefMaker.activeMaking,1,-1 do local m=StuccoReliefMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then StuccoReliefMaker.completeMaking(m); table.remove(StuccoReliefMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(StuccoReliefMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if StuccoReliefMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function StuccoReliefMaker.getStats() return {clayStock=StuccoReliefMaker.clayStock,stoneStock=StuccoReliefMaker.stoneStock,marbleStock=StuccoReliefMaker.marbleStock,paintStock=StuccoReliefMaker.paintStock,silverStock=StuccoReliefMaker.silverStock,goldStock=StuccoReliefMaker.goldStock,jewelStock=StuccoReliefMaker.jewelStock,pearlStock=StuccoReliefMaker.pearlStock,productStock=StuccoReliefMaker.productStock,numBuildings=#StuccoReliefMaker.buildings,hasMaker=StuccoReliefMaker.maker~=nil,makerName=StuccoReliefMaker.maker and StuccoReliefMaker.maker.name or "—",makerSkill=StuccoReliefMaker.maker and StuccoReliefMaker.maker.skill or 0,activeMaking=#StuccoReliefMaker.activeMaking,totalProducts=StuccoReliefMaker.totalProducts} end
return StuccoReliefMaker
